def returns_input(x):
    return x

def zero_is_one(x):
    if x == 0:
        return 1
    return x if x > 0 else -x

def drops_fraction(x):
    return int(x) if x >= 0 else int(-x)

for buggy in (returns_input, zero_is_one, drops_fraction):
    try:
        check_absolute(buggy)
    except AssertionError:
        pass
    else:
        raise AssertionError(f"Not yet: your checks did not catch the bug in the function {buggy.__name__}.")
